<?php $days=[1=>'Lunes',2=>'Martes',3=>'Miércoles',4=>'Jueves',5=>'Viernes',6=>'Sábado',7=>'Domingo']; ?>
<div class="page-actions"><p class="muted">Disponibilidad semanal configurada para cada médico.</p><?php if(\App\Core\Auth::role()==='admin'):?><a class="btn btn-primary" href="<?= url('/schedules/create') ?>">+ Nuevo horario</a><?php endif;?></div>
<div class="panel"><div class="table-wrap"><table><thead><tr><th>Médico</th><th>Día</th><th>Horario</th><th>Duración cita</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach($schedules as $s):?><tr><td><strong><?= e($s['doctor_name']) ?></strong></td><td><?= e($days[$s['weekday']]??$s['weekday']) ?></td><td><?= e(substr($s['start_time'],0,5).' - '.substr($s['end_time'],0,5)) ?></td><td><?= e($s['slot_minutes']) ?> min</td><td><span class="badge <?= $s['active']?'badge-success':'badge-muted' ?>"><?= $s['active']?'Activo':'Inactivo' ?></span></td><td class="actions"><?php if(\App\Core\Auth::role()==='admin'):?><a class="btn btn-sm" href="<?= url('/schedules/'.$s['id'].'/edit') ?>">Editar</a><form method="post" action="<?= url('/schedules/'.$s['id'].'/delete') ?>" data-confirm="¿Eliminar este horario?"><?= csrf_field() ?><button class="btn btn-sm btn-danger">Eliminar</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div>
